void init_systick_timer(uint32_t tick_hz);
__attribute__ ((naked)) void init_sched_stack(uint32_t sched_top_of_stack);
uint32_t get_psp_value(void);
__attribute__ ((naked))void switch_sp_to_psp(void);
void save_psp_value(uint32_t current_psp_value);
__attribute__ ((naked)) void SysTick_Handler(void);

uint32_t psp_of_tasks[MAX_NUM_TASK] ={T1_STACK_START,T2_STACK_START,T3_STACK_START,T4_STACK_START};
uint32_t task_handlers[MAX_NUM_TASK];

uint8_t current_task=0;
int main(void)
{
	enable_processor_faults(); //Just to make sure, we are no accessing any illegal memory or using different stack pointer

	init_sched_stack(SCHED_STACK_START);  //MSP

	task_handlers[0] = (uint32_t)task1_handler;
	task_handlers[1] = (uint32_t)task2_handler;
	task_handlers[2] = (uint32_t)task3_handler;
	task_handlers[3] = (uint32_t)task4_handler;

	init_task_stack(); //stack initialization

	init_systick_timer(TICK_HZ); //to generate systick timer exception

	//In handler mode we use MSP
	//In thread mode we use PSP in this scenario
	//So, need to switch from MSP to PSP after handler mode complete
	switch_sp_to_psp();

	task1_handler();

    /* Loop forever */
	for(;;);
}

