void init_systick_timer(uint32_t tick_hz){
	uint32_t *pSystickReloadValueReg = (uint32_t*)0xE000E014;
	uint32_t *pSystickCntrlStatusReg = (uint32_t*)0xE000E010;
	uint32_t count_value = (SYSTICK_TIMER_CLK / tick_hz) - 1;

	//Configuration of systick timer
	*pSystickCntrlStatusReg |= (1 << 1); //Enables systick exception request
	*pSystickCntrlStatusReg |= (1 << 2); //Indicates the clk source(processor clk source)
    *pSystickCntrlStatusReg |= (1 << 0); //Enables the counter

	//clear the value of Systick Reload Value Register
	*pSystickReloadValueReg &= ~(0x00FFFFFFFF);

	//load the value into the register
	*pSystickReloadValueReg |= count_value;
}

__attribute__ ((naked)) void init_sched_stack(uint32_t sched_top_of_stack){
	__asm volatile("MSR MSP,%0"::"r"(sched_top_of_stack));
	__asm volatile("BX LR");
}

void init_task_stack(void){
	uint32_t*pPSP;
	for(int i = 0; i < MAX_NUM_TASK; i++){
		pPSP = (uint32_t*)psp_of_tasks[i];

		pPSP--;
		*pPSP = DUMMY_XPSR; //0x01000000

		pPSP--; //PC
        *pPSP = task_handlers[i];

        pPSP--; //LR
        *pPSP = 0xFFFFFFFD;

        for(int j=0; j < 13; j ++){ //making all other registers to 0
        	pPSP--;
        	*pPSP = 0;
        }

        //preserve the value of pointer PSP
        psp_of_tasks[i] = (uint32_t)pPSP;


	}
}
void enable_processor_faults(void){
	uint32_t *pSystemHandlerControlStatuReg = (uint32_t*)0xE000ED24;

	*pSystemHandlerControlStatuReg |= (1 << 16); //mem manage fault
	*pSystemHandlerControlStatuReg |= (1 << 17); //bus fault
	*pSystemHandlerControlStatuReg |= (1 << 18); //usage fault
}

uint32_t get_psp_value(void){
	return psp_of_tasks[current_task];
}
__attribute__ ((naked))void switch_sp_to_psp(void){
	//Initialize psp with task1 stack start address
    //get the current value of psp
	__asm volatile("PUSH {LR}"); //presever LR to go back to main
	__asm volatile("BL get_psp_value");
	__asm volatile("MSR PSP,R0"); //initialize PSP
	__asm volatile("POP {LR}"); //pops back the LR value of main

	//change SP to PSP using control register
	__asm volatile("MOV R0,#0x02");
	__asm volatile("MSR CONTROL,R0");
	__asm volatile("BX LR");
}

void save_psp_value(uint32_t current_psp_value){
	psp_of_tasks[current_task] = current_psp_value;
}

void update_next_task(void){
	current_task++;
	current_task = current_task % MAX_NUM_TASK;
}

__attribute__ ((naked)) void SysTick_Handler(void){
	//Step1: Always save the context of the current task
	//get current running task PSP value
	__asm volatile("MRS R0,PSP");

	//using P2P value, store the Stack Frame2(i.e. R4 to R11)
	//using STMDB- Store Multiple Registers Decrement Before
	__asm volatile("STMDB R0!,{R4-R11}");

	//before calling a function, save the LR
	__asm volatile("PUSH {LR}");
	//save the current P2P value
	__asm volatile("BL save_psp_value");


	//Step2: Retrive the context of next task
	//Decide the next task
	__asm volatile("BL update_next_task");

	//get its previous PSP value
	__asm volatile("BL get_psp_value");

	//using new PSP value retrieve Stack Frame 2
	//load multiple registers and increment after
	__asm volatile("LDMIA R0!,{R4-R11}");

	//update PSP and exit
	__asm volatile("MSR PSP,R0");

	//now pop the LR to get back the function
	__asm volatile("POP {LR}");

	__asm volatile("BX LR");
}

